    out.write_text("".join(json.dumps({"id": i, "category": c, "difficulty": d, "expect": e, "question": q,
                                       "gold_sql": s, "patterns": p}) + "\n"
                           for i, c, d, e, p, q, s in CASES))
    print(f"wrote {len(CASES)} cases to {out}")
